import {createContentUI} from './content.js';
import {createDiscussionUI} from './discussion.js';
import {createPlanningUI} from './planning.js';
import {createBusinessUI} from './business.js';
import {createKnowledgeUI} from './knowledge.js';
import {createSourcesUI} from './sources.js';
import {createWorkforceUI} from './workforce.js';
const $=s=>document.querySelector(s);
$('.skip-link').addEventListener('click',event=>{event.preventDefault();$('#main').focus();});
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const stageNames={facts:'等待资料',plan:'待确认计划',draft:'待准备草案',approval:'待我审批',ready:'待提交',submitted:'待核验',observing:'观察中',review:'待验收',completed:'已结束'};
const taskNames={completed:'已完成',pending:'待开始',active:'进行中',approval:'待审批',waiting:'等待资料',paused:'已暂停',observing:'观察中',confirmation:'待确认',acceptance:'待验收'};
const artNames={draft:'草案',accepted:'已验收',verified:'已模拟核验',superseded:'已替代'};
const viewNames={overview:'协同工作台',tasks:'任务中心',employees:'数字员工',applications:'工作应用',knowledge:'知识库','ai-config':'AI基础能力配置',runs:'运行记录',artifacts:'交付物'};
const tabNames={discussion:'讨论',tasks:'任务',artifacts:'交付物',review:'复盘',facts:'资料'};
let state={knowledge:null,sources:null,workforce:null,goals:[],agents:[],runs:[],view:'overview',configTab:'models',goal:sessionStorage.getItem('selectedGoal'),tab:'discussion',filter:'all',details:false};
let fingerprint='',drafts={},targets={},intents={},positions={},sending=new Set(),busy=false,createStep=1,preview=null,sourceGoal=null,createPermission='draft',changeEpoch=0;
async function api(route, options) { const res=await fetch('/api/'+route,{...options,headers:{...options?.headers,...(sessionStorage.getItem('platformToken')?{Authorization:'Bearer '+sessionStorage.getItem('platformToken')}:{})}});const data=await res.json();if(res.status===401&&!$('#access-dialog').open)$('#access-dialog').showModal();if(!res.ok)throw new Error(data.error||'请求失败');return data; }
const post=(route,input)=>api(route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});
const current=()=>state.goals.find(g=>g.id===state.goal);
const agentName=id=>state.workforce?.employees.find(e=>e.id===id)?.name||state.agents.find(a=>a.id===id)?.name||'数字员工';
const shortName=id=>agentName(id).replace(' Agent','');
const date=v=>new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
const money=v=>'¥'+Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const badge=(text,blue=false)=>`<span class="badge ${blue?'blue':''}">${esc(text)}</span>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function heading(title,desc){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><button class="primary" data-new>＋ 新建目标</button></div>`;}
function empty(text,desc){return `<div class="empty-state"><h2>${text}</h2><p>${desc}</p><button class="primary" data-new>新建目标 ↗</button></div>`;}
function scopeRow(label,value){return `<div class="scope-row"><span>${label}</span><strong>${esc(value)}</strong></div>`;}
function context(g){const done=g.tasks.filter(t=>t.status==='completed').length;return `<aside class="goal-context"><button class="secondary details-toggle details-close" data-details>← 返回协作</button><section class="context-section"><div class="context-title"><h3>目标进展</h3>${badge(g.paused?'已暂停':stageNames[g.stage],true)}</div><progress class="progress-bar" value="${done}" max="${g.tasks.length}" aria-label="已完成任务">${done} / ${g.tasks.length}</progress><p>${done} / ${g.tasks.length} 项任务完成 · 计划 v${g.version}</p><p>当前进度代表任务步骤，不代表经营收益。</p></section><section class="context-section"><h3 class="context-heading">业务范围</h3>${scopeRow('店铺',g.scope.store)}${scopeRow('平台',g.scope.platform)}${scopeRow('SKU',g.scope.sku)}${scopeRow('执行边界',g.permission==='approval'?'发布前审批':'只准备草案')}<p>${esc(g.criterion)}</p></section><section class="context-section"><h3 class="context-heading">协作成员</h3><div class="member"><span class="avatar">你</span><div><strong>你</strong><small>目标负责人 · 审批与验收</small></div></div><div class="member"><span class="avatar">AI</span><div><strong>${esc(g.coordinator)}</strong><small>统一协调目标与任务</small></div></div>${discussionUI.people(g).map(id=>`<button class="member" data-mention="${id}"><span class="avatar">${esc(shortName(id).slice(0,1))}</span><div><strong>${esc(agentName(id))}</strong><small>${g.mode==='team'?esc(state.workforce?.employees.find(e=>e.id===id)?.readiness.label||'员工'):g.mode==='platform'?'代码 / HTTP 能力':'历史演示能力'}</small></div><span>@</span></button>`).join('')}</section><section class="context-section"><h3>运行控制</h3><p>暂停目标会阻止后续推进；已提交的动作不能撤回。群聊可继续。</p>${g.stage!=='completed'?`<button class="secondary" data-action="pause">${g.paused?'恢复目标推进':'暂停目标推进'}</button>`:'<p>目标已结束，历史成果已保留。</p>'}</section></aside>`;}
function workspace(){let g=current();if(!g&&state.goals.length){state.goal=state.goals[0].id;g=current();}const list=`<aside class="goal-list"><div class="list-heading"><h2>我的目标</h2><small>${state.goals.length} 个目标</small></div>${state.goals.map(x=>`<button class="goal-item ${g?.id===x.id?'active':''}" data-open="${x.id}"><strong>${esc(x.text)}</strong><small>${x.paused?'已暂停':stageNames[x.stage]} · ${x.contentDraft?'内容制作':x.intent==='selection'?'候选选品':x.kind==='listing'?'商品上新':'经营分析'}</small></button>`).join('')||'<p class="goal-list-empty">从一个具体目标开始</p>'}</aside>`;
 if(!g)return heading('协同工作台','用自然语言给出目标，让团队一起推进。')+`<div class="workbench">${list}<section class="welcome-layout"><span class="eyebrow">目标明确，协作有序</span><h2>说出目标，<br>让每一步都有着落。</h2><p>在群里与数字员工讨论，在任务中确认行动。<br>从一份商品资料，到一次有依据的经营复盘。</p><button class="primary" data-new>新建你的第一个目标 ↗</button><article class="opportunity-card">${badge('机会样例 · 非真实监测')}<h3>给一款角阀，准备可核验的上新资料</h3><p>商品资料 → 内容大纲 → 利润测算 → 人工验收。<br>在同一个目标里体验人类与 Agent 的协作。</p><button class="text-button" data-sample>用这个样例新建目标 →</button></article><div class="welcome-steps"><span>01 明确目标和团队</span><span>02 参与讨论与决策</span><span>03 验收结果和价值</span></div></section></div>`;
 return heading('协同工作台','目标、讨论、行动与结果，在同一个空间。')+`<div class="workbench ${state.details?'details-open':''}">${list}<section class="goal-space"><header class="goal-header"><div class="goal-header-top"><h2>${esc(g.text)}</h2>${badge(g.paused?'已暂停':stageNames[g.stage],true)}<button class="secondary details-toggle" data-details>目标详情</button></div><p>${esc(g.scope.store)} · ${esc(g.scope.sku)} · 计划 v${g.version} · ${g.mode==='team'?'执行 '+g.members.length+' 人 / 讨论 '+discussionUI.people(g).length+' 人':g.members.length+2+' 位成员'}</p></header><div class="goal-tabs" role="group" aria-label="目标工作区">${Object.entries(tabNames).map(([k,n])=>`<button class="${state.tab===k?'active':''}" data-tab="${k}" aria-pressed="${state.tab===k}">${n}${k==='artifacts'&&g.artifacts.length?' '+g.artifacts.length:''}</button>`).join('')}</div><div class="goal-content">${({discussion:discussion,tasks:goalTasks,artifacts:goalArtifacts,review:reviewView,facts:factsView}[state.tab])(g)}</div></section>${context(g)}</div>`;
}
function messageView(m,g){const source=g.messages.find(x=>x.id===m.replyTo);return `<article class="chat-message ${m.role}"><span class="avatar">${m.role==='human'?'你':m.role==='coordinator'?'AI':esc(m.author.slice(0,1))}</span><div class="message-body"><div class="message-meta"><strong>${esc(m.author)}</strong><span>${m.role==='human'?'人类':m.workflow==='check'?'本地能力检查':m.workflow==='handoff'?'任务接收':m.workflow==='delivery'?'实际交付':m.role==='agent'?'专业 Agent':'目标统筹'}</span><time>${date(m.at)}</time></div><div class="message-bubble">${source?`<div class="message-quote">回复：${esc(source.text.slice(0,75))}</div>`:''}${esc(m.text)}</div>${m.mentionAll?`<p class="broadcast-receipt">已通知本群 ${m.targets.length} 位员工${m.skippedTargets?.length?` · ${m.skippedTargets.length} 位暂不可用，已跳过`:""}</p>`:""}${(m.artifactIds||m.upstreamArtifactIds||[]).map(id=>{const a=g.artifacts.find(a=>a.id===id);return a?`<button class="event-link" data-preview="${esc(id)}" data-parent="${g.id}">${icon('file')} ${esc(a.title)} →</button>`:'';}).join('')}${discussionUI.controls(m,g)}${m.card?`<button class="event-link" data-tab="${m.card==='review'||m.card==='completed'?'review':m.card==='facts'?'facts':'tasks'}">${icon('file')} 查看${m.card==='facts'?'商品资料':m.card==='review'||m.card==='completed'?'复盘与验收':'任务与当前动作'} →</button>`:''}</div></article>`;}
const collaborationExpanded=new Map();
document.addEventListener('toggle',e=>{if(e.target.matches?.('[data-collaboration]'))collaborationExpanded.set(e.target.dataset.collaboration,e.target.open);},true);
function collaborationPanel(g){
 if(g.mode!=='team'||g.stage==='completed')return '';
 const c=g.collaboration,missing=c?.checks.filter(x=>x.status==='missing')||[];
 const matching=g.matching;
 const disabled=g.paused?'disabled':'',executeDisabled=g.paused||matching?.missing.length?'disabled':'';
 return `<details class="collaboration-status" data-collaboration="${g.id}" ${collaborationExpanded.get(g.id)?'open':''}><summary>协作进度 · ${esc(stageNames[g.stage])}${g.researchRequest?' · 正在查找来源':''}</summary><section class="collaboration-card" aria-label="协作交接"><div class="section-title"><div><small>协作交接 · 资料 v${g.version}</small><h3>${g.stage==='plan'?'一起推进这个目标':g.stage==='review'?'本轮成果已交付':'团队正在交接成果'}</h3></div>${badge(g.paused?'已暂停':g.stage==='plan'?(missing.length?'待补资料':'待确认执行'):g.runtime?.status==='needs_input'?'等待资料':g.stage==='review'?'待你验收':'执行中')}</div>
 <div class="team-routing"><strong>${g.teamSelection==='auto'?'总控自动安排':'已按你的指定安排成员'}</strong>${g.stage==='plan'?`<button class="text-button" data-team-edit ${g.paused?'disabled':''}>${matching?.missing.length?'补充目标 / 调整成员':'调整成员'}</button>`:''}</div>
 ${matching?`<p class="field-hint">${esc(matching.method)} · 根据目标所需能力与员工可用状态选择，协调工作放在最后。</p><details class="matching-reasons"><summary>为什么选择这些成员</summary>${matching.steps.map(s=>`<p><strong>${esc(s.employeeName)}</strong>：${esc(s.objective)}<br>${esc(s.reasons.join('；'))}</p>`).join('')}</details>${matching.missing.length?`<p class="form-error" role="status">${esc(matching.missing.join('；'))}</p>`:''}`:''}
 ${g.research?`<div class="action-buttons">${actionButton('research',g.researchRequest?'正在查找…':'查找可用来源',true,g.researchRequest?'disabled':disabled)}<button class="text-button" data-view="ai-config/sources">供应商接入</button><button class="text-button" data-view="knowledge">知识库</button></div>`:''}
 ${c?`<ol class="handoff-steps">${g.members.map((id,i)=>`<li><span>${i+1}</span><div><strong>${esc(agentName(id))}</strong><small>${g.runtime?.completed?.includes(id)?'已交付':g.stage==='plan'?'确认后执行':g.members.find(x=>!g.runtime?.completed?.includes(x))===id?'当前处理':'等待前序交付'}</small></div></li>`).join('')}</ol>`:'<p>让总控检查现有成员的能力、资料缺口和交付顺序。</p>'}
 ${g.stage==='plan'?`${missing.length?`<p class="field-hint">${g.research?'总控会先查找已有来源。若缺少目标条件，请在群里说明品类与预算。':'待补：'+esc([...new Set(missing.flatMap(x=>x.missing))].join('；'))}</p>`:''}<div class="action-buttons">${!c?actionButton('kickoff','检查分工与资料',false,disabled):`<button class="secondary" data-tab="facts">查看业务资料</button>${actionButton('kickoff','重新检查',true,disabled)}${g.planProposal?'<button class="primary" data-tab="tasks">确认分工草案</button>':actionButton('plan',missing.length?'按当前资料开始执行':'确认分工并开始',false,executeDisabled)}`}</div>`:g.stage==='review'?`<button class="primary" data-tab="artifacts">查看全部交付物</button>`:['failed','needs_input'].includes(g.runtime?.status)?`<p>${esc(g.runtime.error||'请检查业务资料')}</p><button class="secondary" data-tab="facts">补齐资料</button>${actionButton('retry','重试当前员工',true,disabled)}`:''}
 <p class="field-hint">前序成果会传给后续员工。当前按已装配能力执行；没有数据的步骤会停下并说明原因。</p></section></details>`;
}
function discussion(g){const target=targets[g.id]||'coordinator',intent=intents[g.id]||'discuss';return `${discussionUI.toolbar(g)}<div class="discussion-next"><span>${g.paused?'目标已暂停':stageNames[g.stage]} <strong>${esc(g.tasks.find(t=>t.status!=='completed')?.title||'全部任务已完成')}</strong></span><button class="text-button" data-tab="${g.stage==='facts'?'facts':g.stage==='completed'?'review':'tasks'}">${g.stage==='completed'?'查看复盘':'查看并处理'} →</button></div><div class="chat-area"><div class="chat-log" tabindex="0" aria-label="群聊消息记录">${g.messages.map(m=>messageView(m,g)).join('')}${collaborationPanel(g)}<div class="chat-queue" role="status">${g.repliesPaused?`AI 回复已暂停 · ${g.queue.length} 条待处理`:g.queue.length?`数字员工正在协调回复 · ${g.queue.length} 条待处理`:g.mode==='team'?'模型成员按问题选择Skill；规则成员仅重跑已有校验或计算。':'可以继续讨论；消息不会自动触发发布操作。'}</div></div><form id="chat-form" class="chat-composer" data-goal="${g.id}">${discussionUI.composer(g)}<label class="sr-only" for="chat-input">群聊消息</label><textarea id="chat-input" rows="1" required maxlength="2000" placeholder="说点什么… 输入 @ 可选员工或所有员工" aria-describedby="chat-input-help">${esc(drafts[g.id]||'')}</textarea><div class="composer-bottom"><div class="composer-shortcuts"><button type="button" class="text-button" data-chat-choose aria-label="在消息中插入提及" title="在消息中插入 @">@</button><span>输入 @ 提及员工或所有员工</span><span class="sr-only" id="chat-input-help">Enter 发送，Shift + Enter 换行</span></div><button class="primary" type="submit" ${sending.has(g.id)?'disabled':''}>${sending.has(g.id)?'发送中…':'发送 ↗'}</button></div><details class="chat-options"><summary>消息设置</summary><div class="composer-tools"><label for="chat-target">发送给</label><select id="chat-target"><option value="coordinator">数字员工协调</option>${discussionUI.people(g).map(id=>`<option value="${id}" ${target===id?'selected':''}>@${esc(shortName(id))}</option>`).join('')}</select><label class="sr-only" for="chat-intent">消息用途</label><select id="chat-intent">${[['discuss','讨论 / 提问'],['context','补充背景'],['change','请求变更']].map(([v,n])=>`<option value="${v}" ${intent===v?'selected':''}>${n}</option>`).join('')}</select><button type="button" class="text-button reply-pause" data-action="pauseReplies">${g.repliesPaused?'恢复 AI 回复':'暂停 AI 回复'}</button></div></details><p id="chat-error" role="alert"></p></form></div>`;}
function actionButton(kind,text,secondary=false,extra=''){return `<button class="${secondary?'secondary':'primary'}" data-action="${kind}" ${extra}>${text}</button>`;}
function actionCard(g){if(g.paused)return `<section class="action-card"><h3>目标推进已暂停</h3><p>讨论和查看历史不受影响；恢复后从当前检查点继续。</p><div class="action-buttons">${actionButton('pause','恢复目标推进')}</div></section>`;
 if(['platform','team'].includes(g.mode)&&g.stage==='draft')return platformRuntime(g);
 let title='',desc='',detail='',buttons='';
 if(g.stage==='facts'){title='先核验商品事实，再准备上新';desc='请录入并确认材质、适用规格、成本和库存。代码 Agent 将校验必需信息与配置的价差约束。';buttons='<button class="primary" data-tab="facts">查看并确认资料 →</button>';}
 if(g.stage==='plan'){title=`确认计划 v${g.version}`;desc=g.mode==='team'?'先补充本目标资料，再确认成员交接顺序。模型员工选择已装配 Skill，规则员工按顺序执行。':'按下方顺序推进，每一步有负责人和前置条件。你可以随时在群里补充要求。';buttons=(g.mode==='team'?'<button class="secondary" data-tab="facts">先填写业务资料</button>':'')+actionButton('plan','确认计划',false,g.planProposal?'disabled title="请先采用或放弃分工草案"':'');}
 if(g.stage==='draft'){title='准备有来源的交付物';desc=g.kind==='listing'?'基于已确认样例规格生成标题、参数与售价草案。':'生成分析建议结构；未连接经营数据，不会声称已验证经营结论。';buttons=actionButton('draft','生成演示草案');}
 if(g.stage==='approval'){title=`请审批：新增商品发布 · v${g.version}`;desc='此次授权只覆盖当前版本的单次发布，不包含投放、调价或后续自动经营。';detail=publishDetails(g);buttons=actionButton('approve',g.mode==='platform'?'批准并提交此版本（模拟）':'批准此版本')+'<button class="secondary" data-reject>退回修改</button>';}
 if(g.stage==='ready'){title=`v${g.version} 已批准，尚未提交`;desc='请核对批准内容。此按钮只产生演示回执，不连接真实店铺。';detail=publishDetails(g);buttons=actionButton('execute','模拟提交发布');}
 if(g.stage==='submitted'){title=g.execution.status==='mismatch'?'回读不一致，保持待核验':'请求已提交，等待状态核验';desc=g.execution.status==='mismatch'?g.execution.error+'。重试只回读，不再次发布。':'提交成功不代表上架成功，需要比对平台 SKU、标题、售价与可售状态。';detail=`<p class="note">演示回执 ${esc(g.execution.receipt)} · ${date(g.execution.submittedAt)}</p>`;buttons=actionButton('verify',g.execution.status==='mismatch'?'重试模拟回读':'模拟核验通过')+actionButton('verify','演示回读不一致',true,'data-mismatch="true"');}
 if(g.stage==='observing'){title='核验通过，进入经营观察';desc='观察窗口为上架后7天。尚无实际经营结果；可载入虚构账单体验复盘。';buttons=actionButton('observe','载入 7 天演示观察数据');}
 if(g.stage==='review'){title=g.review?'经营复盘已准备，等待验收':'交付物已准备，等待验收';desc=g.review?'请检查观察窗口、费用口径与目标差距。演示结果不能用于证明真实经营提升。':'此目标只准备草案或建议。请查看交付内容，再决定是否结束。';buttons=`<button class="primary" data-tab="review">查看${g.review?'经营复盘':'交付验收'} →</button>`;}
 if(g.stage==='completed'){title='目标已结束，结果已保留';desc='讨论可以继续。需要新的分析或优化时，另建下一轮目标。';buttons='<button class="secondary" data-followup>创建下一轮优化目标 ↗</button>';}
 if(g.kind==='listing'&&['plan','draft','approval','ready'].includes(g.stage))buttons+='<button class="text-button" data-edit>调整发布内容</button>';
 return `<section class="action-card"><div class="action-kicker">下一步 · ${g.kind==='listing'?'商品上新':'经营分析'}</div><h3>${title}</h3><p>${desc}</p>${detail}<div class="action-buttons">${buttons}</div></section>`;
}
function publishDetails(g){return `<div class="inline-facts"><span>作用范围<strong>${esc(g.scope.store)} / ${esc(g.scope.sku)}</strong></span><span>变更前<strong>无平台商品（模拟新增）</strong></span><span>发布标题<strong>${esc(g.proposal.title)}</strong></span><span>售价 / 库存<strong>${money(g.proposal.price)} / ${g.facts.stock} 件</strong></span></div><p>成本 ${money(g.facts.cost)}，不含完整平台、履约与广告费用，不能作为贡献利润结论。</p><button class="text-button" data-tab="artifacts">先预览当前版本草案 →</button>`;}
function tasksRows(g,global=false){return g.tasks.map((t,i)=>{const visible=state.filter==='all'||state.filter==='attention'&&['waiting','approval','paused','confirmation','acceptance'].includes(t.status)||state.filter==='active'&&['active','observing'].includes(t.status)||state.filter==='completed'&&t.status==='completed';if(global&&!visible)return '';const tag=global?'button':'div';return `<${tag} class="task-row ${t.status}" ${global?`data-open="${g.id}" data-open-tab="tasks"`:''}><span class="task-number">${t.status==='completed'?'✓':String(i+1).padStart(2,'0')}</span><div class="task-text"><strong>${esc(t.title)}</strong><small>${global?esc(g.text)+' · ':''}${esc(shortName(t.owner))} · ${i?'依赖上一项完成':'首个步骤'}</small></div>${badge(taskNames[t.status],['active','approval','confirmation','acceptance'].includes(t.status))}</${tag}>`;}).join('');}
function goalTasks(g){return `<div class="tab-scroll">${planningUI.panel(g)}${actionCard(g)}<div class="section-title"><h3>执行计划</h3><small>${g.tasks.length} 项任务 · v${g.version}</small></div>${tasksRows(g)}<div class="note">确认标准：${esc(g.criterion)}</div><details class="audit-list"><summary>查看 ${g.audit.length} 条操作记录</summary>${g.audit.slice().reverse().map(a=>`<div class="audit-row"><small>${date(a.at)}</small><div><strong>${esc(a.action)} · v${a.version}</strong><p>${esc(a.detail)}</p></div></div>`).join('')}</details></div>`;}
function artifactCard(a,g){return `<article class="artifact-card"><div class="artifact-top">${icon('file')}${badge(artNames[a.status],a.status==='draft')}</div><h3>${esc(a.title)}</h3><p>${esc(g.text)}</p><small>v${a.version} · ${esc(g.scope.sku)}</small><p>${esc(a.evidence)}</p><div class="artifact-actions"><button class="text-button" data-preview="${a.id}" data-parent="${g.id}">预览完整内容 ↗</button><button class="text-button" data-download="${a.id}" data-parent="${g.id}">下载 ↓</button></div></article>`;}
function goalArtifacts(g){return `<div class="tab-scroll"><div class="section-title"><div><h3>目标交付物</h3><p>保留历史版本；审批与发布只使用当前版本。</p></div></div><div class="artifact-grid">${g.artifacts.map(a=>artifactCard(a,g)).join('')||(g.contentDraft&&g.stage==='draft'?'<div class=note role=status>正在编排内容草稿，完成后会显示在这里。若需补充资料或重试，请查看任务标签。</div>':'<div class="note">当前还没有交付物。完成资料和计划确认后，可在任务标签准备草案。</div>')}</div></div>`;}
function factsView(g){if(g.mode==='team')return '<div class="tab-scroll">'+contentUI.facts(g)+businessUI.facts(g)+knowledgeUI.goal(g)+sourcesUI.goal(g)+workforceUI.businessFacts(g,platformFacts(g))+'</div>';if(g.mode==='platform')return platformFacts(g);if(g.kind!=='listing')return `<div class="tab-scroll"><h3>经营资料范围</h3><table class="fact-table"><tr><th>店铺</th><td>${esc(g.scope.store)}</td></tr><tr><th>数据范围</th><td>商品、订单、平台费用与广告费用</td></tr><tr><th>接入状态</th><td>未接入。分析建议仅展示格式，不能据此作出经营决策。</td></tr></table><div class="note">生产接入后，每项分析结论需关联可追溯的数据来源和观察时间。</div><button class="secondary" data-tab="tasks">返回任务计划 →</button></div>`;
 const f=g.facts;return `<div class="tab-scroll"><div class="section-title"><h3>商品事实卡</h3>${badge(f.confirmed?'已确认样例':'待核验',true)}</div><p class="field-hint">商品规格必须来自权威资料，不能由模型猜测补全。</p><table class="fact-table"><caption>${esc(g.scope.product)} · ${esc(g.scope.sku)}</caption>${[['材质',f.material],['接口',f.connector],['采购成本',f.cost===null?'待确认':money(f.cost)],['可售库存',f.stock===null?'待确认':f.stock+' 件'],['资料来源',f.source],['确认记录',f.confirmed?f.confirmedBy+' · '+date(f.confirmedAt):'尚未确认']].map(([k,v])=>`<tr><th>${k}</th><td>${esc(v)}</td></tr>`).join('')}</table><div class="note">全部为虚构样例。原型不会将聊天中的规格直接写入此卡；真实上传、ERP对接与来源冲突处理后续接入。</div>${!f.confirmed?actionButton('facts','载入并确认演示资料',false,g.paused?'disabled':''):'<button class="primary" data-tab="tasks">查看任务计划 →</button>'}${g.paused?'<p class="field-hint">目标暂停中，请从目标详情恢复后再确认。</p>':''}</div>`;}
function reviewView(g){const r=g.review||(g.kind==='analysis'?g.analysis:null);let body='';if(r){body=`<div class="section-title"><h3>经营复盘</h3>${badge(g.review?'虚构样例':'录入账单 · 代码计算')}</div><p class="field-hint">${esc(r.window)} · ${esc(r.source)}</p><div class="review-stats"><div><span>净销售额</span><strong>${money(r.netSales)}</strong></div><div><span>贡献利润</span><strong>${money(r.profit)}</strong></div><div><span>贡献利润率</span><strong>${r.rate===null?'—':esc(r.rate)+'%'}</strong></div></div><table class="fact-table"><caption>贡献利润 = 净销售额 − 全部归属可变成本</caption>${[['净销售额',r.netSales],['商品成本',r.goods],['平台与支付费用',r.fees],['履约费用',r.fulfillment],['归因广告费用',r.ads],['售后额外损失',r.returns],['其他可变费用',r.other],['贡献利润',r.profit]].map(([k,v])=>`<tr><th>${k}</th><td>${money(v)}</td></tr>`).join('')}</table><div class="note">净销售额已扣除退款本金；售后损失只记额外成本，避免重复扣减。<br>${esc(r.result)}</div>`;}
 else if(['review','completed'].includes(g.stage))body=`<h3>交付验收</h3><p class="field-hint">本目标仅准备${g.contentDraft?'内容草稿':g.kind==='listing'?'上新草案':'分析建议'}，没有执行真实或模拟发布。</p><div class="note">验收标准：${esc(g.criterion)}</div>${g.artifacts.filter(a=>a.version===g.version).map(a=>artifactCard(a,g)).join('')}`;
 else body=`<h3>复盘等待中</h3><p class="field-hint">${g.permission==='approval'?'先完成发布核验，再观察7天数据。动作核验通过与经营达标是两个不同结果。':'完成交付物后，在这里确认验收。'}</p><div class="note">当前没有足够资料评估结果，不将缺失数据展示为零收入。</div><button class="secondary" data-tab="tasks">查看当前任务 →</button>`;
 if(g.stage==='review')body+=`<div class="action-buttons">${actionButton('complete',r?'确认复盘并结束目标':'确认交付并结束目标',false,g.paused?'disabled':'')}<button class="text-button" data-tab="discussion">回群继续讨论</button></div>${g.paused?'<p class="field-hint">目标暂停中，请先恢复。</p>':''}`;
 if(g.stage==='completed')body+='<div class="note">负责人已验收，目标已结束。历史结果和讨论将保留。</div><button class="primary" data-followup>创建下一轮优化目标 ↗</button>';
 return `<div class="tab-scroll">${body}</div>`;}
function globalTasks(){const rows=state.goals.map(g=>tasksRows(g,true)).join('');return heading('任务中心','等待资料、人工审批与执行进度，统一跟进。')+`<div class="global-filters" role="group" aria-label="筛选任务">${[['all','全部任务'],['attention','待我处理'],['active','执行中'],['completed','已完成']].map(([v,n])=>`<button data-filter="${v}" class="${state.filter===v?'active':''}" aria-pressed="${state.filter===v}">${n}</button>`).join('')}</div><div class="panel">${rows||'<div class="empty-state"><h2>这里暂时没有任务</h2><p>创建目标后，会同步建立相关执行任务。</p></div>'}</div>`;}
function globalArtifacts(){return heading('交付物','目标内与全局视图共享成果，版本和来源始终可追溯。')+`<div class="artifact-grid">${state.goals.flatMap(g=>g.artifacts.map(a=>artifactCard(a,g))).join('')||'<div class="panel"><h2>等待第一份成果</h2><p>从目标的任务计划生成草案后，这里会同步展示。</p></div>'}</div>`;}
function legacyEmployees(){return heading('数字员工','业务岗位负责目标，专业 Agent 按需提供能力。')+`<div class="role-note"><div><h3>一位目标协调者，组织一支专业团队</h3><p>上新由商品运营数字员工负责；分析由经营分析数字员工负责。每个目标拥有独立的上下文和任务记录。</p></div><span>规划 → 执行 → 检查 → 继续</span></div><div class="agent-grid">${state.agents.map(a=>`<article class="panel agent-card"><div class="artifact-top"><span class="avatar">${esc(a.initials)}</span>${badge('专业能力 · 演示')}</div><h2>${esc(a.name)}</h2><p>${esc(a.role)}</p><p class="field-hint">按需参与目标；尚未接入真实模型与外部工具。</p><button class="text-button" data-agent="${a.id}">邀请到新目标 ↗</button></article>`).join('')}</div>`;}

function fitChatInput(){const el=$('#chat-input');if(el){el.style.height='44px';el.style.height=Math.min(120,Math.max(44,el.scrollHeight))+'px';}}
document.addEventListener('input',e=>{if(e.target.id==='chat-input')fitChatInput();});
function capture(){const form=$('#chat-form'),input=$('#chat-input'),log=$('.chat-log');if(!form)return null;const id=form.dataset.goal,s={id,focus:document.activeElement===input,start:input?.selectionStart,end:input?.selectionEnd,scroll:log?.scrollTop||0,bottom:!log||log.scrollHeight-log.scrollTop-log.clientHeight<70};positions[id]=s;return s;}
function render(force=false){const next=JSON.stringify(state);if(!force&&next===fingerprint)return;if(!force&&(document.querySelector('#mention-menu')?.hidden===false||document.querySelector('#discussion-dialog')?.open))return;if(!force&&!busy&&document.activeElement?.closest('#facts-form,#ledger-form,#skill-data-form,#reference-form,#source-search,#kb-search,#kb-goal-form,#business-data-form,#copy-data-form'))return;capture();discussionUI.hide();fingerprint=next;$('#main').classList.toggle('conversation-page',state.view==='overview'&&state.goals.length>0);$('#main').innerHTML=({overview:workspace,tasks:globalTasks,artifacts:globalArtifacts,employees:workforceUI.employees,applications:workforceUI.applicationsPage,knowledge:workforceUI.knowledgePage,'ai-config':workforceUI.capabilityPage,runs:runsView}[state.view])();$('#page-crumb').textContent=viewNames[state.view];$('#nav-count').textContent=state.goals.flatMap(g=>g.tasks).filter(t=>['waiting','approval','confirmation','acceptance'].includes(t.status)).length;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view.split('/')[0]===state.view);b.setAttribute('aria-current',b.dataset.view.split('/')[0]===state.view?'page':'false');});const more=$('[data-nav-more]');if(more){const active=['ai-config','tasks','runs','artifacts'].includes(state.view);more.classList.toggle('active',active);more.setAttribute('aria-current',active?'page':'false');}const saved=positions[state.goal]||{bottom:true},log=$('.chat-log'),input=$('#chat-input');fitChatInput();if(log)log.scrollTop=saved.bottom?log.scrollHeight:saved.scroll;if(input&&saved.focus){input.focus({preventScroll:true});input.setSelectionRange(saved.start,saved.end);}}
function applyRoute(route){
 const aliases={capabilities:'applications',connections:'ai-config/models',agents:'ai-config/legacy',sources:'ai-config/sources'};
 route=aliases[route]||route;const [view,tab]=route.split('/');state.view=viewNames[view]?view:'overview';
 state.configTab=['models','skills','external','sources','catalog','legacy'].includes(tab)?tab:'models';
 const canonical=state.view==='ai-config'?'ai-config/'+state.configTab:state.view;
 return canonical;
}
function go(route){const canonical=applyRoute(route);$('#navigation-dialog')?.close();location.hash=canonical;render(true);}

function openGoal(id,tab='discussion'){capture();state.goal=id;state.tab=tab;state.details=false;sessionStorage.setItem('selectedGoal',id);go('overview');}
function receive(g){changeEpoch++;const i=state.goals.findIndex(x=>x.id===g.id);if(i<0)state.goals.unshift(g);else state.goals[i]=g;render();}
async function act(kind,extra={},id=state.goal){const result=await post(`goals/${id}/actions`,{kind,expectedVersion:state.goals.find(g=>g.id===id)?.version,...extra});receive(result);return result;}
async function refresh(){const epoch=changeEpoch;try{const [agents,goals,runs,workforce,sources,knowledge]=await Promise.all([api('agents'),api('goals'),api('runs'),api('workforce'),api('sources'),api('knowledge')]);if(busy||epoch!==changeEpoch)return;state.agents=agents;state.goals=goals;state.runs=runs;state.workforce=workforce;state.sources=sources;state.knowledge=knowledge;await updateRunPreview();$('#connection-state').textContent='服务已连接';render();}catch(err){$('#connection-state').textContent='连接中断';if(!state.agents.length)$('#main').innerHTML='<div class="panel empty-state"><h2>暂时无法连接</h2><p>请确认服务已启动，页面将自动重试。</p></div>';}}
function openCreate(text='',kind='analysis',only=null,source=null){sourceGoal=source;createMembersTouched=false;createKindManual=kind==='listing'||!!only;createRequestId=globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);createStep=1;createPermission='draft';$('#goal').value=text;$('#team-recommendation').textContent='';$('#goal-kind').value=kind;$('#create-store').value='慕雅居示例店';$('#create-sku').value=kind==='listing'?'DEMO-JF-001':'全店汇总';$('#create-product').value=kind==='listing'?'角阀':'经营分析';$('#create-price').value='29.90';$('#form-error').textContent='';$('#create-engine').value=only&&state.agents.some(a=>a.id===only)?'legacy':'team';$('#team-selection').value=only?'manual':'auto';syncTeamChoice();updateCreateMembers(kind,only);showCreateStep();$('#task-dialog').showModal();$('#goal').focus();}
function syncTeamChoice(){const manual=$('#create-engine').value==='legacy'||$('#team-selection').value==='manual';$('#manual-team-options').hidden=!manual;$('#auto-team-hint').hidden=manual;$('#team-selection').disabled=$('#create-engine').value==='legacy';}
$('#team-selection').onchange=syncTeamChoice;
$('#create-engine').addEventListener('change',syncTeamChoice);
function showCreateStep(){const first=createStep===1;$('#create-step-one').hidden=!first;$('#create-step-two').hidden=first;$('#create-back').hidden=first;$('#create-hint').hidden=!first;$('#new-step').textContent='新建目标 · '+createStep+' / 2';$('#submit-task').textContent=first?'下一步：确认范围 →':'创建目标并进入协作 ↗';if(!first){const listing=$('#goal-kind').value==='listing';$('#scope-preview').innerHTML=`<h3>${esc($('#goal').value)}</h3>${scopeRow('负责成员',$('#create-engine').value==='team'?($('#team-selection').value==='auto'?'总控将按目标自动安排，无需手动选人':'保留你指定的成员'):listing?'商品运营数字员工':'经营分析数字员工')}${scopeRow('业务范围','由下方填写的店铺与 SKU / 分析范围确定')}${scopeRow('交付标准',listing?(createPermission==='draft'?'核验规格、准备上新草案并验收；不执行发布':'核验规格、准备草案；审批发布后观察7天'):'形成分析建议，负责人确认验收')}${scopeRow('资料准备度',listing?'待核验 · 创建后补齐演示资料':'创建后自动检查各员工所需资料')}`;$('#goal-permission').disabled=!listing||$('#create-engine').value==='team';$('#goal-permission').value=listing&&$('#create-engine').value!=='team'?createPermission:'draft';$('#create-price').parentElement.hidden=!listing;$('#scope-note').textContent='填写业务范围后，商品资料和经营账单在目标内补充。输入数据未自动同步店铺；发布动作仍为模拟。';}}
$('#goal-kind').onchange=()=>{createKindManual=true;const listing=$('#goal-kind').value==='listing';$('#create-sku').value=listing?'DEMO-JF-001':'全店汇总';$('#create-product').value=listing?'角阀':'经营分析';updateCreateMembers($('#goal-kind').value);};
$('#goal-permission').onchange=e=>{createPermission=e.target.value;showCreateStep();};
$('#close-dialog').onclick=()=>$('#task-dialog').close();$('#create-back').onclick=()=>{createStep=1;$('#form-error').textContent='';showCreateStep();$('#goal').focus();};
async function recommendTeam(){
 const text=$('#goal').value.trim();if(!text||$('#create-engine').value!=='team')return;
 let recommendation=await post('workforce/recommend',{text});if(!recommendation.recipes.length&&!recommendation.employeeIds.length){$('#team-recommendation').textContent='暂未匹配业务工作包，请手动选择员工；不会猜测不存在的能力。';return;}
 for(const recipe of recommendation.recipes)await post('workforce/install',{recipeId:recipe.id});await refresh();recommendation=await post('workforce/recommend',{text});
 if(recommendation.missing.length)throw new Error('所需员工尚未就绪：'+recommendation.missing.join('、'));
 updateCreateMembers($('#goal-kind').value);document.querySelectorAll('[name=agents]').forEach(c=>c.checked=recommendation.employeeIds.includes(c.value));createMembersTouched=true;
 $('#team-recommendation').textContent='按关键词与已装配能力推荐：'+(recommendation.labels||recommendation.recipes.map(r=>r.name)).join(' → ')+'。请确认成员和业务范围；不是模型自主规划。';
}
$('#recommend-team').onclick=async()=>{const b=$('#recommend-team');b.disabled=true;try{await recommendTeam();}catch(err){$('#form-error').textContent=err.message;}finally{b.disabled=false;}};
$('#task-form').onsubmit=async e=>{e.preventDefault();const automatic=$('#create-engine').value==='team'&&$('#team-selection').value==='auto',members=[...document.querySelectorAll('[name=agents]:checked')].map(x=>x.value);if(!$('#goal').value.trim()||(!automatic&&!members.length)){$('#form-error').textContent='请填写目标，并至少邀请一位配置就绪的成员。';return;}if(createStep===1){if(!createKindManual){$('#submit-task').disabled=true;try{const suggestion=await post('goal-preview',{text:$('#goal').value});const previousKind=$('#goal-kind').value;$('#goal-kind').value=suggestion.kind;if(previousKind!==suggestion.kind&&!createMembersTouched&&$('#create-engine').value==='legacy')updateCreateMembers(suggestion.kind);$('#create-sku').value=suggestion.sku||(suggestion.kind==='listing'?'DEMO-JF-001':'全店汇总');$('#create-product').value=suggestion.product||(suggestion.kind==='listing'?'角阀':'经营分析');}catch(err){$('#form-error').textContent=err.message;return;}finally{$('#submit-task').disabled=false;}}createStep=2;showCreateStep();$('#new-title').tabIndex=-1;$('#new-title').focus();return;}const b=$('#submit-task');b.disabled=true;busy=true;try{const g=await post('goals',{text:$('#goal').value,...($('#create-engine').value==='team'?{employeeIds:automatic?[]:members,teamSelection:automatic?'auto':'manual',startCollaboration:true}:{members}),kind:$('#goal-kind').value,permission:$('#goal-permission').value,sourceGoal,requestId:createRequestId,scope:{store:$('#create-store').value,sku:$('#create-sku').value,product:$('#create-product').value},proposal:$('#goal-kind').value==='listing'?{price:$('#create-price').value,title:$('#create-product').value}:undefined});receive(g);$('#task-dialog').close();openGoal(g.id);toast('目标、协作群与任务已同时创建');}catch(err){$('#form-error').textContent=err.message;}finally{b.disabled=false;busy=false;}};
function download(a){const text=`# ${a.title}\n\n版本：v${a.version} · ${artNames[a.status]}\n\n> 根据录入资料准备，未自动核对外部平台\n\n${a.body}\n\n来源：${a.evidence}`;const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=a.title+'-v'+a.version+'.md';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#team-close').onclick=()=>$('#team-dialog').close();
$('#team-edit-mode').onchange=()=>{$('#team-edit-members').hidden=$('#team-edit-mode').value==='auto';};
document.addEventListener('click',e=>{if(!e.target.closest('[data-team-edit]'))return;const g=current();$('#team-dialog').dataset.goal=g.id;$('#team-dialog').dataset.version=g.version;$('#team-goal-text').value=g.text;$('#team-edit-mode').value=g.teamSelection||'manual';$('#team-edit-members').hidden=$('#team-edit-mode').value==='auto';$('#team-edit-error').textContent='';$('#team-member-options').innerHTML=state.workforce.employees.map(e=>`<label class="team-member-option"><input type="checkbox" name="teamEmployee" value="${esc(e.id)}" ${g.members.includes(e.id)?'checked':''} ${e.readiness.ready?'':'disabled'}><span>${esc(e.name)}<small>${esc(e.readiness.ready?e.skillIds.map(id=>state.workforce.skills.find(s=>s.id===id)?.name||id).join('、'):e.readiness.blockers.join('；'))}</small></span></label>`).join('');$('#team-dialog').showModal();});
$('#team-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const g=await post(`goals/${$('#team-dialog').dataset.goal}/actions`,{kind:'setTeam',expectedVersion:Number($('#team-dialog').dataset.version),text:$('#team-goal-text').value,teamSelection:$('#team-edit-mode').value,employeeIds:[...document.querySelectorAll('[name=teamEmployee]:checked')].map(e=>e.value)});receive(g);$('#team-dialog').close();toast('总控已保存新的成员安排');}catch(error){$('#team-edit-error').textContent=error.message;}finally{b.disabled=false;}};
$('#close-artifact').onclick=()=>$('#artifact-dialog').close();$('#download-preview').onclick=()=>{if(preview)download(preview);};$('#close-edit').onclick=()=>$('#edit-dialog').close();$('#close-reject').onclick=()=>$('#reject-dialog').close();
$('#edit-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;busy=true;try{await act('revise',{title:$('#publish-title').value,price:$('#publish-price').value},$('#edit-dialog').dataset.goal);$('#edit-dialog').close();state.tab='tasks';render(true);toast('已生成新版本，旧审批已失效');}catch(err){$('#edit-error').textContent=err.message;}finally{b.disabled=false;busy=false;}};
$('#reject-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;busy=true;try{await act('reject',{reason:$('#reject-reason').value,approvalId:state.goals.find(g=>g.id===$('#reject-dialog').dataset.goal)?.approval?.id},$('#reject-dialog').dataset.goal);$('#reject-dialog').close();toast('审批已退回，需重新准备');}catch(err){$('#reject-error').textContent=err.message;}finally{b.disabled=false;busy=false;}};
document.addEventListener('input',e=>{if(e.target.id==='chat-input')drafts[e.target.form.dataset.goal]=e.target.value;});
document.addEventListener('change',e=>{if(e.target.name==='agents')createMembersTouched=true;if(e.target.id==='chat-target')targets[state.goal]=e.target.value;if(e.target.id==='chat-intent')intents[state.goal]=e.target.value;});
document.addEventListener('keydown',e=>{if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229){e.preventDefault();e.target.form.requestSubmit();}});
document.addEventListener('submit',async e=>{if(e.target.id!=='chat-form')return;e.preventDefault();const id=e.target.dataset.goal;if(sending.has(id))return;const text=$('#chat-input').value,target=$('#chat-target').value,intent=$('#chat-intent').value;const b=e.submitter||e.target.querySelector('[type=submit]');sending.add(id);b.disabled=true;try{const g=await post(`goals/${id}/actions`,{kind:'message',text,target,intent,...discussionUI.submission(state.goals.find(g=>g.id===id),text)});discussionUI.sent(id);if(drafts[id]===text)drafts[id]='';receive(g);if(state.goal===id){$('#chat-input')?.focus();const log=$('.chat-log');if(log)log.scrollTop=log.scrollHeight;}}catch(err){if(state.goal===id&&$('#chat-error'))$('#chat-error').textContent=err.message;else toast(err.message);}finally{sending.delete(id);if(state.goal===id){const live=$('#chat-form [type=submit]');if(live){live.disabled=false;live.textContent='发送 ↗';}}}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;let ownsAction=false;try{
 if(b.hasAttribute('data-business-center'))go('applications');
 if(b.hasAttribute('data-kb-center'))go('knowledge');
 if(b.hasAttribute('data-source-center'))go('ai-config/sources');
 if(b.hasAttribute('data-new'))openCreate();
 if(b.hasAttribute('data-sample'))openCreate('为角阀准备商品资料、内容大纲与经营测算，交付后由我验收','listing');
 if(b.dataset.agent)openCreate('',b.dataset.agent==='product'||b.dataset.agent==='content'?'listing':'analysis',b.dataset.agent);
 if(b.dataset.employeeGoal){const e=state.workforce.employees.find(e=>e.id===b.dataset.employeeGoal);openCreate('请'+e.name+'协助完成：'+state.workforce.skills.find(s=>s.id===e.skillIds[0]).name,['merchandise','creative','risk'].includes(e.roleId)?'listing':'analysis',e.id);}
 if(b.hasAttribute('data-nav-more'))$('#navigation-dialog').showModal();
 if(b.hasAttribute('data-nav-close'))$('#navigation-dialog').close();
 if(b.dataset.view)go(b.dataset.view);
 if(b.dataset.open)openGoal(b.dataset.open,b.dataset.openTab||'discussion');
 if(b.dataset.tab){state.tab=b.dataset.tab;state.details=false;render(true);}
 if(b.dataset.filter){state.filter=b.dataset.filter;render(true);}
 if(b.hasAttribute('data-details')){state.details=!state.details;render(true);}
 if(b.dataset.mention){targets[state.goal]=b.dataset.mention;state.tab='discussion';state.details=false;render(true);$('#chat-input')?.focus();}
 if(b.dataset.action){if(busy)return;busy=true;ownsAction=true;b.disabled=true;const g=current(),extra={};if(b.dataset.action==='approve'){extra.version=g.version;extra.approvalId=g.approval.id;}if(b.dataset.mismatch)extra.mismatch=true;await act(b.dataset.action,extra);if(b.dataset.action==='facts'){state.tab='tasks';render(true);}if(b.dataset.action==='observe'||b.dataset.action==='complete'){state.tab='review';render(true);}toast('操作已记录');}
 if(b.hasAttribute('data-edit')){const g=current();$('#edit-dialog').dataset.goal=g.id;$('#publish-title').value=g.proposal.title;$('#publish-price').value=g.proposal.price;$('#edit-error').textContent='';$('#edit-dialog').showModal();}
 if(b.hasAttribute('data-reject')){$('#reject-dialog').dataset.goal=state.goal;$('#reject-reason').value='';$('#reject-error').textContent='';$('#reject-dialog').showModal();}
 if(b.dataset.preview||b.dataset.download){const g=state.goals.find(x=>x.id===b.dataset.parent),a=g.artifacts.find(x=>x.id===(b.dataset.preview||b.dataset.download));if(b.dataset.download)download(a);else{preview=a;$('#artifact-title').textContent=a.title;$('#artifact-meta').textContent=`v${a.version} · ${artNames[a.status]} · 数据来源见正文`;$('#artifact-body').textContent=a.body;$('#artifact-evidence').textContent='来源：'+a.evidence;$('#artifact-dialog').showModal();}}
 if(b.hasAttribute('data-followup')){const g=current();openCreate('基于上一轮目标，分析商品贡献利润与退款情况，提出下一轮优化建议','analysis',null,g.id);}
 }catch(err){toast(err.message);}finally{if(ownsAction){busy=false;b.disabled=false;}}});
window.addEventListener('hashchange',()=>{const canonical=applyRoute(location.hash.slice(1));if(location.hash.slice(1)!==canonical)history.replaceState(null,'','#'+canonical);$('#navigation-dialog')?.close();render(true);});
const runNames={queued:'排队中',running:'执行中',succeeded:'成功',needs_input:'等待资料',failed:'失败',interrupted:'已中断',discarded:'旧版本已丢弃',waiting_resume:'等待恢复'};
let configEditing=null,testRunId=null,runPreviewId=null,createRequestId=null,createKindManual=false,createMembersTouched=false;
function runRows(runs){return runs.length?runs.slice(0,100).map(r=>`<button class="task-row" data-run="${r.id}"><span class="avatar">${r.purpose==='test'?'测':'执'}</span><div class="task-text"><strong>${esc(r.agentName)} · ${['test','skill_test','model_test','employee_test','external_test'].includes(r.purpose)?'配置测试':r.purpose==='chat'?'群聊请求':'目标执行'}</strong><small>${date(r.createdAt)} · 配置v${r.configVersion} · ${r.durationMs===undefined?'待计时':r.durationMs+' ms'}${r.error?' · '+esc(r.error):''}</small></div>${badge(runNames[r.status]||r.status,['queued','running'].includes(r.status))}</button>`).join(''):'<div class="note">暂无运行记录。可以在 Agent 配置中执行测试，或确认目标计划。</div>';}
function platformEmployees(){return '<div class=section-title><h2>旧版规则 / HTTP 适配器</h2></div>'+`<div class="role-note"><div><h3>旧版规则模块与 HTTP 适配器</h3><p>商品校验与利润计算使用你录入的数据。外部 Agent 可通过 HTTP 适配器接入；当前内置 Agent 不依赖大模型。</p></div>${badge('服务端持久化',true)}</div><div class="agent-grid">${state.agents.map(a=>`<article class="panel agent-card"><div class="artifact-top"><span class="avatar">${esc(a.initials)}</span>${badge(a.enabled?'已启用':'已停用',a.enabled)}</div><h2>${esc(a.name)}</h2><p>${esc(a.role)}</p><div class="config-meta">${scopeRow('适配器',a.adapter==='builtin'?'内置代码 Agent':'外部 HTTP Agent')}${scopeRow('配置版本','v'+a.revision)}${scopeRow('超时',a.timeoutMs/1000+' 秒')}${scopeRow('能力',a.capabilities.join(' / '))}</div><div class="action-buttons"><button class="primary" data-config="${a.id}">配置与测试</button><button class="text-button" data-agent="${a.id}" ${a.enabled?'':'disabled'}>用于新目标 ↗</button></div></article>`).join('')}</div><section class="panel runtime-panel"><div class="section-title"><h3>最近调用</h3><button class="text-button" data-view="runs">全部运行记录 →</button></div>${runRows(state.runs.slice(0,5))}</section>`;}
function runsView(){return heading('运行记录','每次 Agent 调用都保存配置版本、输入、结构化结果和异常。')+`<div class="panel">${runRows(state.runs)}</div>`;}
function platformRuntime(g){const r=g.runtime||{};return `<section class="action-card"><div class="action-kicker">后端自动执行 · ${esc(runNames[r.status]||'等待调度')}</div><h3>${r.status==='failed'?'本步骤调用失败':r.status==='needs_input'?'需要补齐数据后继续':'数字员工正在按计划推进'}</h3><p>${esc(r.error||'无需反复点击生成。主协调器按顺序调用所选能力，并保存每一步的交付物。')}</p>${r.missing?.length?`<div class="note">待处理：${r.missing.map(esc).join('、')}</div>`:''}<div class="action-buttons">${['failed','needs_input'].includes(r.status)?`<button class="primary" data-tab="facts">检查并补充资料</button>${actionButton('retry','重试当前步骤',true)}${g.mode==='team'?actionButton('replan','重新安排分工',true):''}`:''}${g.kind==='listing'?'<button class="text-button" data-edit>调整发布内容</button>':''}${r.runId?`<button class="text-button" data-run="${r.runId}">查看本次调用 →</button>`:''}</div></section>`;}
function field(name,label,value='',type='text',attrs=''){return `<div><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}></div>`;}
function platformFacts(g){const locked=g.paused||!(g.kind==='listing'?['facts','plan','draft']:['plan','draft']).includes(g.stage);const f=g.facts||{},ledger=g.financials||{};
 const controls=g.kind==='listing'?`${field('material','材质',f.confirmed?f.material:'','text','required maxlength="500"')}${field('connector','接口 / 适用规格',f.confirmed?f.connector:'','text','required maxlength="500"')}${field('cost','采购成本（元）',f.cost,'number','required min="0" max="1000000000" step="0.01"')}${field('stock','可售库存（件）',f.stock,'number','required min="0" max="1000000000" step="1"')}${field('source','资料来源',f.confirmed?f.source:'','text','required maxlength="500"')}`:`${[['netSales','净销售额'],['goods','商品成本'],['fees','平台及支付费用'],['fulfillment','履约费用'],['ads','归因广告费用'],['returns','售后额外损失'],['other','其他可变成本']].map(([k,n])=>field(k,n+'（元，可留空）',ledger[k],'number','min="0" max="1000000000000" step="0.01"')).join('')}${field('window','统计期间',ledger.window,'text','required maxlength="120"')}${field('source','账单来源',ledger.source,'text','required maxlength="500"')}`;
 return `<div class="tab-scroll"><div class="section-title"><div><h3>${g.kind==='listing'?'商品资料录入':'经营账单录入'}</h3><p class="field-hint">数据保存在后端，Agent 将据此校验或计算。缺失数值请留空，不以 0 代替未知。</p></div></div><div class="note">${esc(g.scope.store)} · ${esc(g.scope.sku)}${g.kind==='listing'?' · 售价 '+money(g.proposal.price):''}</div><form id="${g.kind==='listing'?'facts-form':'ledger-form'}" data-goal="${g.id}"><fieldset ${locked?'disabled':''}><div class="data-fields">${controls}</div>${g.kind==='listing'?'<label class="confirm-check"><input name="confirmed" type="checkbox" required> 我已核对所填资料及来源</label>':'<p class="field-hint">净销售额已扣退款本金；售后损失只计额外成本，避免重复扣减。</p>'}<div class="action-buttons"><button type="submit" class="primary">保存${g.kind==='listing'?'并确认资料':'账单'}</button><button type="button" class="secondary" data-fill-data="${g.kind}">填入演示样例</button></div></fieldset><p class="form-error" id="data-error" role="alert"></p></form>${locked?'<div class="note">当前阶段不允许覆盖已确认输入。暂停时先恢复；已生成成果后，另建跟进目标或按内容变更重新审批。</div>':''}</div>`;
}
async function openConfig(id){const a=state.agents.find(a=>a.id===id);configEditing=structuredClone(a);testRunId=null;$('#test-agent').disabled=false;$('#config-title').textContent=a.name+' · 配置与测试';for(const key of ['name','role','adapter','timeoutMs','endpoint','secretEnv','instructions'])$('#cfg-'+key).value=a[key];$('#cfg-enabled').checked=a.enabled;$('#cfg-threshold').value=a.id==='product'?a.settings.minGrossMargin:a.settings.targetProfitRate;$('#threshold-label').textContent=a.id==='product'?'最低采购价差率（%）':'贡献利润率目标（%）';$('#config-revision').textContent='当前已保存版本 v'+a.revision;$('#config-error').textContent='';$('#agent-test-result').textContent='测试使用服务端已保存的配置。修改后请先保存。';$('#agent-test-input').value=JSON.stringify(await api(`agents/${id}/sample`),null,2);updateAdapterFields();$('#agent-config-dialog').showModal();}
function updateAdapterFields(){const remote=$('#cfg-adapter').value==='http';$('#remote-config').hidden=!remote;$('#cfg-instructions').disabled=!remote;$('#builtin-note').hidden=remote;}
async function updateRunPreview(){
 if(testRunId&&$('#agent-config-dialog').open){const id=testRunId;const r=await api('runs/'+id);if(id!==testRunId||!$('#agent-config-dialog').open)return;$('#agent-test-result').textContent=`${runNames[r.status]} · 配置v${r.configVersion}\n${r.error||''}\n${r.result?JSON.stringify(r.result,null,2):'等待后端执行…'}`;$('#test-agent').disabled=['queued','running'].includes(r.status);}
 if(runPreviewId&&$('#run-dialog').open){const id=runPreviewId;const r=await api('runs/'+id);if(id!==runPreviewId||!$('#run-dialog').open)return;$('#run-title').textContent=r.agentName+' · '+runNames[r.status];$('#run-meta').textContent=`运行 ${r.id} · 配置v${r.configVersion} · ${r.durationMs??'—'} ms`;$('#run-input').textContent=JSON.stringify(r.input,null,2);$('#run-output').textContent=JSON.stringify({status:r.status,error:r.error||undefined,result:r.result,trace:r.trace},null,2);}
}
$('#close-config').onclick=()=>{$('#agent-config-dialog').close();testRunId=null;};$('#cfg-adapter').onchange=updateAdapterFields;
$('#agent-config-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const input={revision:configEditing.revision,enabled:$('#cfg-enabled').checked,settings:{[configEditing.id==='product'?'minGrossMargin':'targetProfitRate']:Number($('#cfg-threshold').value)}};for(const key of ['name','role','adapter','timeoutMs','endpoint','secretEnv','instructions'])input[key]=$('#cfg-'+key).value;const result=await api('agents/'+configEditing.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});configEditing=result;$('#config-revision').textContent='已保存版本 v'+result.revision;$('#config-error').textContent='';toast('配置已保存，后续调用使用新版本');await refresh();}catch(err){$('#config-error').textContent=err.message;}finally{b.disabled=false;}};
$('#test-agent').onclick=async()=>{const b=$('#test-agent');b.disabled=true;try{let input;try{input=JSON.parse($('#agent-test-input').value);}catch{throw new Error('测试输入不是有效JSON');}const r=await post(`agents/${configEditing.id}/test`,{input});testRunId=r.id;await updateRunPreview();await refresh();}catch(err){$('#agent-test-result').textContent=err.message;b.disabled=false;}};
$('#close-run').onclick=()=>{$('#run-dialog').close();runPreviewId=null;};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.config)await openConfig(b.dataset.config);if(b.dataset.run){runPreviewId=b.dataset.run;$('#run-input').textContent='正在载入输入…';$('#run-output').textContent='正在载入结果…';$('#run-dialog').showModal();await updateRunPreview();}if(b.dataset.fillData){const values=b.dataset.fillData==='listing'?{material:'黄铜（演示）',connector:'G1/2（演示）',cost:12,stock:200,source:'内置虚构商品样例'}:{netSales:3000,goods:1200,fees:150,fulfillment:300,ads:600,returns:150,other:0,source:'内置虚构经营账单',window:'演示第1–7天'};for(const [k,v] of Object.entries(values))$('#field-'+k).value=v;toast('已填入演示数据，请核对后保存');}}catch(err){toast(err.message);}});
document.addEventListener('submit',async e=>{if(!['facts-form','ledger-form'].includes(e.target.id))return;e.preventDefault();const form=e.target,id=form.dataset.goal,b=e.submitter;b.disabled=true;busy=true;try{const data=Object.fromEntries(new FormData(form));const g=state.goals.find(g=>g.id===id);await act(form.id==='facts-form'?'facts':'ledger',form.id==='facts-form'?{facts:data,confirmed:data.confirmed==='on',expectedVersion:g.version}:{financials:data,expectedVersion:g.version},id);state.tab='tasks';render(true);toast('资料已保存，请确认当前版本计划');}catch(err){$('#data-error').textContent=err.message;}finally{b.disabled=false;busy=false;}});
$('#access-form').onsubmit=async e=>{e.preventDefault();sessionStorage.setItem('platformToken',$('#access-token').value);$('#access-dialog').close();await refresh();};


function updateCreateMembers(kind,only){$('#agent-options').innerHTML=$('#create-engine').value==='team'?workforceUI.memberOptions(kind,only):state.agents.filter(a=>a.enabled).map(a=>`<label class="agent-option"><input type="checkbox" name="agents" value="${a.id}" ${!only||only===a.id?'checked':''}>${esc(a.name)}</label>`).join('');}
$('#create-engine').onchange=()=>{updateCreateMembers($('#goal-kind').value);showCreateStep();};
const sourcesUI=createSourcesUI({state,api,esc,badge,toast,refresh,render,act});
const knowledgeUI=createKnowledgeUI({state,api,esc,badge,toast,refresh,render,act});
const discussionUI=createDiscussionUI({state,api,esc,receive,render,targets,drafts});
const planningUI=createPlanningUI({state,api,esc,badge,receive,render});
const businessUI=createBusinessUI({state,api,esc,badge,toast,refresh,render,openCreate,act});
const contentUI=createContentUI({state,api,esc,receive,openGoal,render,act});
const workforceUI=createWorkforceUI({contentUI,businessUI,knowledgeUI,sourcesUI,state,api,esc,badge,toast,refresh,render,navigate:go,legacyPage:platformEmployees,openRun:async id=>{runPreviewId=id;$('#run-input').textContent='正在载入…';$('#run-output').textContent='正在载入…';$('#run-dialog').showModal();await updateRunPreview();}});

const initialRoute=applyRoute(location.hash.slice(1)||'overview');if(location.hash.slice(1)!==initialRoute)history.replaceState(null,'','#'+initialRoute);
await refresh();setInterval(refresh,1800);
